const lead = $json;

function clean(v) {

    if (v === undefined || v === null)
        return "";

    return String(v).trim();

}

lead["First Name"] = clean(lead["First Name"]);
lead["Last Name"] = clean(lead["Last Name"]);
lead["Company Name"] = clean(lead["Company Name"]);
lead["Job Title"] = clean(lead["Job Title"]);
lead["Industry"] = clean(lead["Industry"]);
lead["Country"] = clean(lead["Country"]);
lead["City"] = clean(lead["City"]);

lead["LinkedIn Profile URL"] =
clean(lead["LinkedIn Profile URL"])
.toLowerCase()
.replace(/\/$/, "");

lead["Company Website"] =
clean(lead["Company Website"]);

return [{
    json: lead
}];

const required = [
    "First Name",
    "Last Name",
    "LinkedIn Profile URL",
    "Company Name"
];

const errors = [];

for (const field of required) {

    const value = String($json[field] ?? "")
        .trim();

    if (
        value === "" ||
        value.toLowerCase() === "(leave blank)" ||
        value.toLowerCase() === "null"
    ) {

        errors.push(field);

    }

}

return [{
    json: {
        ...$json,
        valid: errors.length === 0,
        validationErrors: errors.join(", ")
    }
}];

const lead = $('Validate Lead').first().json;

const mapping = {

    "CHIEF EXECUTIVE OFFICER":"CEO",
    "CEO / FOUNDER":"FOUNDER",
    "CO-FOUNDER":"FOUNDER",
    "FOUNDER & CEO":"FOUNDER",
    "OWNER / CEO":"OWNER",
    "VICE PRESIDENT":"VP",
    "VP FINANCE":"VP",
    "VP SALES":"VP",
    "MANAGING DIR":"MANAGING DIRECTOR"

};

let seniority =
String(lead["Seniority"] || "")
.trim()
.toUpperCase();

lead["Seniority"] =
mapping[seniority] ||
seniority;

const allowed =
$input.all()
.filter(i =>
String(i.json.Enabled).toUpperCase()=="TRUE"
)
.map(i =>
String(i.json.Seniority)
.toUpperCase()
);

return [{

json:{

...lead,

decisionMaker:
allowed.includes(
lead["Seniority"]
)

}

}];

const lead = $json;

if (!lead["Lead ID"]) {

    lead["Lead ID"] =
        "L-" +
        Date.now() +
        "-" +
        Math.random().toString(36).substring(2,8);

}

return [{
    json: lead
}];

